import{_ as r,o as a,c as l,j as e,a as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/probleme/tutorials-statistik-fehler-darstellung.png",m=JSON.parse('{"title":"Fehler bei der Statistikvorbereitung und Abgabe beheben","description":"","frontmatter":{"title":"Fehler bei der Statistikvorbereitung und Abgabe beheben","source_pageid":1197,"source_revision":4935},"headers":[],"relativePath":"hilfe/probleme/fehleranalyse-zur-statistik-tutorial.md","filePath":"hilfe/probleme/fehleranalyse-zur-statistik-tutorial.md"}'),d={name:"hilfe/probleme/fehleranalyse-zur-statistik-tutorial.md"};function o(h,n,u,c,b,k){return a(),l("div",null,[...n[0]||(n[0]=[e("h1",{id:"fehler-bei-der-statistikvorbereitung-und-abgabe-beheben",tabindex:"-1"},[i("Fehler bei der Statistikvorbereitung und Abgabe beheben "),e("a",{class:"header-anchor",href:"#fehler-bei-der-statistikvorbereitung-und-abgabe-beheben","aria-label":'Permalink to "Fehler bei der Statistikvorbereitung und Abgabe beheben"'},"​")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),i("Hinweis – Geltungsbereich: ASDPC-Verfahren")]),e("p",null,[i("Dieser Artikel beschreibt die Vorbereitung beziehungsweise Nutzung des bisherigen ASDPC-Verfahrens. Für die amtliche Erhebung "),e("strong",null,"ab dem Schuljahr 2027/2028"),i(" ist die Umstellung auf das Statistikmodul des SVWS-Servers angekündigt. Beachten Sie den "),e("a",{href:"https://www.svws.nrw.de/statistik/asdpc-svws-server",target:"_blank",rel:"noreferrer"},"offiziellen Zeitplan"),i(" und die Vorgaben der jeweiligen Erhebung.")])],-1),t('<p>Suchen Sie nach bekannten Fehlern bei Installation, Darstellung und Abgabe der Statistik. Für technische Fragen zu ASDPC und den Abgabedateien verweist die Anleitung an IT.NRW.</p><p>Auf dieser Seite werden in der Praxis häufiger auftretende Fehler beschrieben, die zu Beginn oder am Ende der Statistik auftreten können.</p><p>Kontaktieren Sie zu <em>technischen</em> Problemen mit der Statistik, zum Beispiel die Installation und Konfiguration des Programms oder Erzeugen, Verwenden und Übersenden von Schlüsseldateien oder der Statistikdatei, den Support von IT.NRW.</p><h2 id="vor-der-statistik" tabindex="-1">Vor der Statistik <a class="header-anchor" href="#vor-der-statistik" aria-label="Permalink to &quot;Vor der Statistik&quot;">​</a></h2><h3 id="asdpc-auf-einem-monitor-mit-hoher-auflosung" tabindex="-1">ASDPC auf einem Monitor mit hoher Auflösung <a class="header-anchor" href="#asdpc-auf-einem-monitor-mit-hoher-auflosung" aria-label="Permalink to &quot;ASDPC auf einem Monitor mit hoher Auflösung&quot;">​</a></h3><p><a href="/bilder/probleme/tutorials-statistik-fehler-darstellung.png"><img src="'+s+'" alt="ASDPC wird auf einem Monitor mit hoher Auflösung ausgeführt. Es funktioniert alles, der &quot;Hauptbildschirm&quot; ist aufgrund der Position der Scrollbalken nicht zu sehen. Hier muss das Fenster passend verschoben werden. Wenn die Scrollbalken nicht angezeigt wurden, ist ASDPC möglicherweise nicht korrekt installiert, d.h. es müssen auf dem lokalen Rechner .dll-Dateien registriert werden. Achten Sie hierbei auf den korrekten Speicherort der aktuellen .dlls." loading="lazy"></a></p><p><em>ASDPC wird auf einem Monitor mit hoher Auflösung ausgeführt. Es funktioniert alles, der &quot;Hauptbildschirm&quot; ist aufgrund der Position der Scrollbalken nicht zu sehen. Hier muss das Fenster passend verschoben werden. Wenn die Scrollbalken nicht angezeigt wurden, ist ASDPC möglicherweise nicht korrekt installiert, d.h. es müssen auf dem lokalen Rechner .dll-Dateien registriert werden. Achten Sie hierbei auf den korrekten Speicherort der aktuellen .dlls.</em></p><p>Wird ASDPC auf einem Monitor mit hoher Auflösung ausgeführt, werden die Inhalte nicht korrekt dargestellt. In diesem Falle sind die Scrollbalken unten und rechts zu nutzen, um die Inhalte in den sichtbaren Bereich zu verschieben.</p><h3 id="asdpc-wurde-auf-dem-rechner-nicht-installiert-bzw-die-dll-wurden-nicht-registriert" tabindex="-1">ASDPC wurde auf dem Rechner nicht installiert bzw. die .dll wurden nicht registriert <a class="header-anchor" href="#asdpc-wurde-auf-dem-rechner-nicht-installiert-bzw-die-dll-wurden-nicht-registriert" aria-label="Permalink to &quot;ASDPC wurde auf dem Rechner nicht installiert bzw. die .dll wurden nicht registriert&quot;">​</a></h3><p>ASDPC wird falsch dargestellt - das heißt, das Programm startet, aber Menüs des Programms werden nicht angezeigt - wenn keine korrekte Installation als Windows-Administrator durchgeführt wurde oder wenn die notwendigen .dll-Bibliotheken nicht korrekt installiert wurden.</p><p>Konsultieren Sie hierzu die Hilfeseite zu ASDPC, auf ihr liegt eine Anleitung, um dieses Problem zu lösen. Alternativ kontaktieren Sie bei weiterhin falscher Darstellung von ASDPC den Support von IT.NRW.</p><p>Probieren Sie, die .dll-Dateien korrekt zu <a href="/hilfe/probleme/hilfe-bei-problemen-verwaltung-statistik-fuer-it-nrw.html">registrieren</a>.</p><h3 id="statistik-dll-konflikte-bei-paralleler-installation-von-schild-nrw2" tabindex="-1">Statistik.dll-Konflikte bei paralleler Installation von SchILD-NRW2 <a class="header-anchor" href="#statistik-dll-konflikte-bei-paralleler-installation-von-schild-nrw2" aria-label="Permalink to &quot;Statistik.dll-Konflikte bei paralleler Installation von SchILD-NRW2&quot;">​</a></h3><p>Grundsätzlich können SchILD-NRW2 und SchILD-NRW3 parallel auf einem Rechner betrieben werden.</p><p>Hierbei ist aber zu beachten, dass jeweils nur eine Statistik-Datei (jeweils <em>schulver.mdb</em> und die <em>ASDTABS.mdb</em>) verwendet werden kann!</p><p>Beide Dateien liegen im Unterordner <em>\\IT-NRW\\</em> im SchILD-NRW-Installationsverzeichnis.</p>',16),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),i("Wichtig")]),e("p",null,[i("Es wird von allen SchILD-NRW-Installationen die .dll genutzt, "),e("em",null,"die zuletzt auf dem verwendeten Windows-Client registriert wurde"),i(".")])],-1),e("p",null,"Dies gilt auch für eventuell mehrere Installationen von SchILD-NRW2 oder SchILD-NRW3. Die Dateien werden bei der Installation von SchILD-NRW automatisch registriert.",-1),e("p",null,"Sind alle .dlls aktuell, ist kein Problem zu erwarten.",-1),e("p",null,"Wird irgendwann SchILD-NRW2 nicht weiter geupdatet, könnte unabhängig vom immer aktuellen Stand von SchILD-NRW3 dauerhaft die veraltete Datei aus dem SchILD-NRW-2-Verzeichnis genutzt werden und zu Fehlern führen.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),i("Hinweis")]),e("p",null,"Diese Ausführungen gelten auch, wenn SchILD-NRW als Netzwerkinstallation neben einer lokalen Einzelplatzinstallation auf dem Windows-Rechner verwendet wird - auf dem Windows-Rechner kann nur eine .dll registriert sein!")],-1),t('<p>Führen Sie aus einer Installation von SchILD-NRW das nachträgliche <a href="/hilfe/probleme/hilfe-bei-problemen-verwaltung-statistik-fuer-it-nrw.html">Registrieren</a> der zu dieser Installation gehörenden Datei aus. Achten Sie bitte darauf, dass die ASDTABS.MDB dieser Installation dann auch die aktuelle ist.</p><h3 id="fehler-mit-den-schlusseln" tabindex="-1">Fehler mit den Schlüsseln <a class="header-anchor" href="#fehler-mit-den-schlusseln" aria-label="Permalink to &quot;Fehler mit den Schlüsseln&quot;">​</a></h3><p>Siehe hierzu die Dokumentation von IT.NRW zum Schlüsselmanagement.</p><ol><li>Achten Sie darauf, dass Ihr PRIVATER Schlüssel geheim bleibt und IT.NRW den jeweils aktuellen öffentlichen Schlüssel korrekt zugesandt bekommen hat.</li><li>Achten Sie darauf, kein neues Schlüsselpaar zu generieren, wenn dies nicht beabsichtigt ist. Sollte ein neues Schlüsselpaar generiert worden sein, muss IT.NRW der neue öffentliche Schlüssel zugesandt werden.</li></ol><h2 id="bei-der-abgabe" tabindex="-1">Bei der Abgabe <a class="header-anchor" href="#bei-der-abgabe" aria-label="Permalink to &quot;Bei der Abgabe&quot;">​</a></h2><h3 id="versand-an-eine-inkorrekte-e-mailadresse" tabindex="-1">Versand an eine inkorrekte E-Mailadresse <a class="header-anchor" href="#versand-an-eine-inkorrekte-e-mailadresse" aria-label="Permalink to &quot;Versand an eine inkorrekte E-Mailadresse&quot;">​</a></h3><p>Entnehmen Sie die richtige Empfängeradresse den aktuellen Unterlagen von IT.NRW. Prüfen Sie die Schreibweise genau. In der Praxis treten beispielsweise folgende Fehler auf:</p><ul><li>statistik.schule<strong>n</strong>@... ➥ hier ist das &quot;n&quot; zu viel.</li><li>statistik@.... ➥ hier fehlt &quot;.schule&quot;.</li><li>statisik@... ➥ diverse (!) mögliche Tippfehler des Wortes &quot;Statistik&quot;.</li><li>schluessel.schule@... ➥ Möglicherweise wurde eine vom Schlüsselaustausch im Mailprogramm gespeicherte Adresse verwendet und somit wurde die Statistik an die falsche Adresse geschickt.</li><li>statistik@schule.nrw ➥ Hier fehlt am Ende das &quot;.de&quot;.</li></ul><p>Kontrollieren Sie auch, ob Ihr E-Mail-Programm eine Fehlermeldung zum Versand angezeigt hat. Solche Meldungen können übersehen werden.</p><h3 id="versand-von-inkorrekten-dateien" tabindex="-1">Versand von inkorrekten Dateien <a class="header-anchor" href="#versand-von-inkorrekten-dateien" aria-label="Permalink to &quot;Versand von inkorrekten Dateien&quot;">​</a></h3><p>Es soll die Datei V4[SCHULNUMMER].[JAHR]X versendet werden. In der Praxis kann es vorkommen, dass stattdessen eine andere Datei verschickt wurde, z.B.</p><ul><li>die Vorgabedaten</li><li>eine Statistikdatei aus einem vorherigen Schuljahr</li><li>eine Schlüsseldatei</li><li>eine Datenbank &quot;asdpc.mbd&quot;, entweder als Original oder eine ihrer Sicherungsdateien</li><li>eine pdf-Datei, die für einen Papierausdruck erzeugt wurde</li><li>die Programmdatei ASDPC32.exe</li><li>die Statistik wurde mit einer Vorjahresversion von ASDPC erstellt</li><li>es wurde vergessen, die Datei anzuhängen</li></ul><h3 id="keine-bestatigungsmail-erhalten" tabindex="-1">Keine Bestätigungsmail erhalten <a class="header-anchor" href="#keine-bestatigungsmail-erhalten" aria-label="Permalink to &quot;Keine Bestätigungsmail erhalten&quot;">​</a></h3><p>Nach dem Versand sollten Sie innerhalb der Arbeitszeiten von IT.NRW eine Eingangsbestätigung erhalten. Bleibt sie aus, prüfen Sie folgende mögliche Ursachen:</p><ul><li>der Maileingang bei IT.NRW wird erst am folgenden Werktag bearbeitet.</li><li>die Mail befindet sich noch im Postausgang der Mailsoftware.</li><li>die Statistik wurde an die falsche E-Mailadresse geschickt. Kontrollieren Sie bitte, ob Ihre E-Mail korrekt verschickt wurde und ob Sie die korrekten Datei angehängt haben.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fehleranalyse_zur_Statistik_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4935.</p>',17)])])}const f=r(d,[["render",o]]);export{m as __pageData,f as default};
